mapper.sql:
where 1=1

		and cpes_llave = #{llaveTabla}


		and cpes_estado = #{estado}


		and cpes_tipo = #{tipo}


		and cpes_estadodocumento = #{estadoDocumento}


		and cpes_nombre = #{nombre}


		and cpes_proceso = #{proceso}


		and (upper(cpes_nombre) like upper('%' || #{filtroParametro} || '%'))
